import math

def build_agent(sandbox):
    cabin = sandbox.get_vehicle_cabin()
    if cabin is None:
        raise ValueError("Cart not found")
    beams = []
    for (xx, yy) in [(4.8, 2.6), (4.9, 2.6), (5.0, 2.6), (5.1, 2.6), (5.2, 2.6)]:
        b = sandbox.add_beam(xx, yy, 0.16, 0.32, angle=0, density=10.0)
        sandbox.add_joint(cabin, b, (xx, yy), type="rigid")
        beams.append(b)
    return cabin

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_vehicle_position()
    x, y = pos
    vel = sandbox.get_vehicle_velocity()
    vx, vy = vel
    speed = math.hypot(vx, vy)

    # Apply force in mud zone to counteract resistance
    if 5.5 <= x <= 7.5:
        sandbox.apply_force(agent_body, (500, 0))
    # Apply impulse in first impulse zone to boost speed
    elif 8.0 <= x <= 9.0 and not hasattr(agent_action, 'applied_impulse1'):
        sandbox.apply_force(agent_body, (300, 0))
        setattr(agent_action, 'applied_impulse1', True)
    # Apply impulse in second impulse zone to maintain speed
    elif 10.5 <= x <= 11.0 and not hasattr(agent_action, 'applied_impulse2'):
        sandbox.apply_force(agent_body, (200, 0))
        setattr(agent_action, 'applied_impulse2', True)
    # Apply forward force in decel zone to counteract resistance
    elif 9.5 <= x <= 11.0:
        sandbox.apply_force(agent_body, (300, 0))

    # Speed trap check: ensure speed is at least 2.8 m/s when crossing x=9.0
    if x >= 9.0 and not hasattr(agent_action, 'crossed_speed_trap'):
        if speed < 2.8:
            sandbox.apply_force(agent_body, (250, 0))
        setattr(agent_action, 'crossed_speed_trap', True)

    # Checkpoint check: ensure speed is between 1.1 and 2.7 m/s when crossing x=11.0
    if x >= 11.0 and not hasattr(agent_action, 'crossed_checkpoint'):
        if speed < 1.1:
            sandbox.apply_force(agent_body, (100, 0))
        elif speed > 2.7:
            sandbox.apply_force(agent_body, (-100, 0))
        setattr(agent_action, 'crossed_checkpoint', True)

